const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('primeval','From Latin primaevus “of the first age,” formed from primus “first” + aevum “age.”',[C('primeval.s1','natural history','The fossils came from a primeval sea that existed before flowering plants evolved.','这些化石来自开花植物出现之前的远古海洋。','primeval sea','adjective before noun','Primeval can refer to the very distant past near the beginning of the world.'),C('primeval.s2','wilderness','A primeval forest still covered the valley, untouched by roads or logging.','未经道路或伐木破坏的原始森林仍覆盖着山谷。','primeval forest','adjective before noun','The second sense describes a wild state not altered by humans.')],M('The primeval forest was a recently planted park crossed by highways.','The primeval forest remained wild and untouched by human development.','Primeval in this sense means in an original, undeveloped natural state.','meaning'),[Q(1,'When did the primeval sea exist?','before flowering plants evolved','after modern cities were built','during a recent storm','Primeval can describe the earliest stages of the world.'),Q(2,'What made the forest primeval?','it remained untouched by people','it was planted last year','it was crossed by highways','This sense emphasizes an original wild state.'),Q(1,'Which scene is primeval?','a landscape from the world’s earliest ages','a new shopping district','a recently paved road','The adjective can mean belonging to the distant beginning.'),Q(2,'What does primeval describe in “primeval wilderness”?','land still in its original wild state','land carefully landscaped for tourists','a modern industrial site','The sense means not changed by humans.')]);
P('primitive','From Latin primitivus “first or earliest,” from primus “first.”',[C('primitive.s1','history','The exhibit showed primitive tools made by some of the earliest human communities.','展览展示了早期人类社群制作的原始工具。','primitive tools','adjective before noun','This sense refers to an early stage of human or technical development.'),C('primitive.s2','technology','The cabin had a primitive stove that heated only one small room.','小屋里有一台简陋的炉子，只能给一间小屋供暖。','primitive stove','adjective before noun','Primitive can also mean very simple and not advanced or comfortable.'),C('primitive.s3','art','The gallery displayed works by a self-taught primitive whose style used simple shapes.','画廊展出了一个自学成才的朴拙派艺术家的作品，他的风格使用简洁形状。','a self-taught primitive','noun after article','The noun can refer to an artist of a deliberately simple style; use this label carefully.')],M('The cabin had primitive heating because it used a fully automated central system in every room.','The cabin had primitive heating because one simple stove warmed only a small room.','Primitive in this sense means rudimentary, not advanced or comprehensive.','meaning'),[Q(1,'What did the exhibit show?','tools from early human communities','modern electric drills','postcards from a museum','Primitive can refer to an early stage of human development.'),Q(2,'Why was the stove primitive?','it heated only one small room','it controlled the entire city','it was a modern central system','The adjective can mean simple and limited.'),Q(3,'What style did the artist use?','simple shapes','photorealistic digital effects','a complex mechanical system','The noun sense can describe an artist of a simple style.'),Q(2,'Which device is primitive?','a basic heater with one control','a networked climate system in every room','a new high-efficiency boiler','Primitive means simple and not advanced.')]);
P('primordial','From Late Latin primordialis, from primordium “beginning,” formed from primus “first” + the stem of ordiri “to begin.”',[C('primordial.s1','geology','Scientists found signs of primordial life in rocks formed near the planet’s earliest oceans.','科学家在形成于地球最早海洋附近的岩石中发现了原始生命迹象。','primordial life','adjective before noun','The adjective can mean existing from the beginning of the world or life.'),C('primordial.s2','analysis','Trust is a primordial condition for cooperation, not a decorative extra.','信任是合作的根本条件，而不是可有可无的装饰。','primordial condition','noun complement','Primordial can also mean the most basic or foundational.')],M('Trust was called primordial because it was an optional detail added after cooperation was complete.','Trust was called primordial because it was a basic condition for cooperation.','Primordial in the foundational sense means basic and original.','meaning'),[Q(1,'When did the primordial life exist?','near the beginning of life on Earth','after the first cities','during the last decade','Primordial means existing from the beginning.'),Q(2,'Why is trust called primordial?','it is a foundational condition','it is a decorative extra','it is added after cooperation','This sense means basic and original.'),Q(1,'Which evidence might be primordial?','traces from the earliest life','a recent factory record','a future prediction','The adjective refers to the earliest beginning.'),Q(2,'Choose a close meaning of primordial here.','fundamental','recent','optional','The second sense means most basic.')]);
P('prince','From Old French prince, from Latin princeps “chief, first person,” formed from primus “first” + capere “take.”',[C('prince.s1','royalty','The prince greeted visitors at the palace before the national celebration.','全国庆典前，王子在王宫迎接来访者。','the prince greeted visitors','noun subject','A prince is a male royal family member, often the son of a monarch.'),C('prince.s2','leadership','The newspaper called her a prince of comedy for shaping the country’s modern satire.','报纸称她为喜剧界巨擘，因为她塑造了该国现代讽刺艺术。','a prince of comedy','metaphorical title','Prince can figuratively mean a leading man in a field.')],M('The prince was the monarch’s daughter and female heir.','The prince was the monarch’s son and male royal heir.','Prince names a male royal; a monarch’s daughter is a princess.','meaning'),[Q(1,'Who greeted the visitors?','a male royal family member','the monarch’s daughter','a postal worker','The core sense of prince is a male member of a royal family.'),Q(2,'Why was she called a prince of comedy?','she was a leading figure in the field','she inherited a throne','she worked as a palace guard','The figurative sense means a field’s leading man/person.'),Q(1,'Which person is a prince in the source sense?','a king’s son','a queen’s daughter','a court building','A prince is especially the son of a king or queen.'),Q(2,'What does “prince of comedy” praise?','exceptional leadership in comedy','royal ancestry','a role in a postal office','The phrase uses prince figuratively for a field leader.')]);
P('princess','From Old French princesse, the feminine form of prince; ultimately from Latin princeps “chief.”',C('princess.s1','royalty','The princess represented her family at the opening of the children’s hospital.','公主代表王室出席了儿童医院的开院仪式。','princess represented her family','noun subject','A princess is a king’s daughter or a prince’s wife.'),M('The princess was described as a king’s son and male heir.','The princess was described as a king’s daughter and royal representative.','Princess names a female royal family member, not a son.','meaning'),[Q(1,'Who represented the royal family?','a princess','a postmaster','a potter','A princess is a female member of a royal family.'),Q(1,'Which relation can make someone a princess?','being a king’s daughter','being a king’s son','being a court building','The source definition includes a king’s daughter.'),Q(1,'What did she attend?','the hospital opening','a prizefight','a pottery kiln','The example says she represented her family at the opening.'),Q(1,'Which title may also describe a princess?','a prince’s wife','a mail sorter','a parliament building','The source sense also includes the wife of a prince.')]);
P('principality','From Old French principalite and Late Latin principalitas, from principalis “chief, first in importance,” ultimately from princeps “chief”; it names territory governed by a prince.',C('principality.s1','government','The principality maintained its own laws under the rule of a hereditary prince.','这个公国在世袭亲王统治下保有自己的法律。','principality maintained','noun subject','A principality is a territory governed by a prince.'),M('The principality was a territory ruled by an elected postal clerk rather than a prince.','The principality was a territory governed by a prince.','A principality is defined by princely rule.','meaning'),[Q(1,'Who governed the principality?','a hereditary prince','a postal clerk','a village potter','A principality is a territory ruled by a prince.'),Q(1,'What did it maintain?','its own laws','a cooking recipe','a printing press','The context describes its legal status.'),Q(1,'Which place could be a principality?','a small territory ruled by a prince','a forest with no government','a factory department','The noun names a princely territory.'),Q(1,'Which historical place may be called a principality?','a territory governed by a prince','a city governed only by a mayor','a farm owned by a family','The defining feature is princely rule.')]);
P('principally','From principal + adverb suffix -ly; principal comes from Latin principalis “first, chief.”',[C('principally.s1','composition','The archive contains principally letters, with a few maps and photographs.','档案主要由信件构成，另有少量地图和照片。','contains principally letters','adverb modifying verb','This sense means mostly or mainly.'),C('principally.s2','purpose','The grant was awarded principally to support research by early-career scientists.','这笔拨款尤其是为了支持职业生涯早期的科学家开展研究。','principally to support','adverb modifying infinitive','Principally can introduce the chief reason or purpose.')],M('The archive contains principally letters, but letters form only one tiny item in a collection dominated by films.','The archive contains principally letters, which make up most of its collection.','Principally means mainly, so the main component should be letters.','meaning'),[Q(1,'What makes up most of the archive?','letters','maps only','photographs only','Principally means mainly or mostly.'),Q(2,'Why was the grant awarded?','chiefly to support early-career research','to buy a royal title','to mail the archive','The second sense introduces a main purpose.'),Q(1,'Choose a synonym for principally.','mainly','rarely','accidentally','Principally means mostly.'),Q(2,'Which phrase uses the purpose sense?','The fund was principally intended for training.','The file is principally blue.','The postman arrived principally.','The first sentence says what the fund chiefly aimed to do.')]);
P('principled','From principle + -ed, with -ed meaning “having or guided by”; it describes conduct based on moral rules.',C('principled.s1','ethics','The principled auditor reported the conflict of interest even though the disclosure delayed the project.','这位有原则的审计员报告了利益冲突，尽管披露此事拖慢了项目。','principled auditor','adjective before noun','Principled means acting according to clear moral standards.'),M('The principled auditor hid the conflict of interest to protect a friend.','The principled auditor disclosed the conflict despite personal pressure.','Principled conduct follows moral rules even when inconvenient.','meaning'),[Q(1,'Why was the auditor principled?','reported the conflict despite the delay','hid it to help a friend','changed the report for payment','Principled describes adherence to moral standards.'),Q(1,'Which action is principled?','disclosing a conflict of interest','concealing it for personal gain','destroying the audit','A principled person follows ethical rules.'),Q(1,'What does -ed suggest in principled?','guided by or having principles','happening in the past only','belonging to a prince','The adjective means having moral principles.'),Q(1,'Choose the closest meaning of principled.','ethical','deceptive','careless','A principled action follows moral rules.')]);
P('principles','From Latin principium “beginning, foundation,” via principle; the plural names moral rules or standards that guide behavior.',C('principles.s1','ethics','Her principles would not allow her to approve a report she knew was false.','她的原则不允许她批准一份自己明知不实的报告。','her principles would not allow','subject + modal','Principles are moral rules that guide behavior.'),M('He acted on his principles by knowingly approving a false report.','He acted on his principles by refusing to approve a report he knew was false.','Ethical principles guide someone away from knowingly endorsing falsehood.','meaning'),[Q(1,'What did her principles prevent?','approving a false report','checking the report','writing a clear summary','Principles guide moral choices.'),Q(1,'Which item is a principle?','a rule against falsifying evidence','a printer cartridge','a royal title','Principles are rules or standards for behavior.'),Q(1,'Why did she refuse approval?','she knew the report was false','the printer was out of paper','the project was completed','Her standards would not permit endorsing false information.'),Q(1,'What do principles guide?','behavior and decisions','postal routing','light through glass','The source sense defines them as rules guiding behavior.')]);
P('print','From Old French preinte “impression,” the feminine past participle of preindre “press, crush,” from Latin premere “press”; later senses cover machine printing, print handwriting, marks, and paper photographs.',[C('print.s1','publishing','The press will print the revised handbook before the conference begins.','印刷厂会在会议开始前印出修订版手册。','will print the handbook','verb + object','The verb means produce text or images on paper with a machine.'),C('print.s2','handwriting','Please print your full name rather than joining the letters in cursive.','请用印刷体写出全名，不要像草书那样连写字母。','print your full name','imperative verb','Print can mean write letters separately.'),C('print.s3','evidence','A muddy shoe left a clear print beside the garden gate.','一只沾泥的鞋在花园门旁留下了清晰的印痕。','left a clear print','verb + object','A print can be a mark left on a surface.'),C('print.s4','photography','She framed a black-and-white print of the harbor.','她把一张黑白冲印照片装进了相框。','print of the harbor','noun + of-phrase','A print can mean a photograph on paper.')],M('Please print your full name by joining all the letters into one cursive line.','Please print your full name with the letters separated.','Print as a writing instruction asks for unjoined letters.','usage'),[Q(1,'What will the press do to the handbook?','produce copies on paper','leave a muddy footprint','take a photograph only','Print as a verb can produce text on paper.'),Q(2,'How should the name be written?','with separate letters','in joined cursive','as a shoe mark','The handwriting sense means use block letters.'),Q(3,'What did the muddy shoe leave?','a mark on the ground','a handbook','a framed photograph','Print can mean an impression left on a surface.'),Q(4,'What did she frame?','a paper photograph','a postal code','a printer machine','A photographic print is an image on paper.')]);
P('printed','From print + -ed, describing something produced by a printing process rather than written by hand.',C('printed.s1','publishing','The printed schedule was posted beside the entrance for visitors to consult.','印刷好的日程表贴在入口旁供访客查看。','printed schedule','adjective before noun','Printed can describe text or designs put onto paper or cloth by printing.'),M('The printed schedule consisted of words written by hand in pencil.','The printed schedule consisted of text reproduced by a printing process.','Printed contrasts with handwritten.','meaning'),[Q(1,'What was posted by the entrance?','a schedule produced in print','a clay pot','a private soldier','Printed means put onto a surface by a printing process.'),Q(1,'How does printed differ from handwritten?','it was mechanically reproduced','it was written by hand','it was spoken aloud','The adjective distinguishes printed text from handwriting.'),Q(1,'Which item is printed?','a mass-produced leaflet','a note written in pencil','an unwritten thought','Printed describes material made by printing.'),Q(1,'Where could printed patterns appear?','on paper or cloth','only inside a computer chip','only on a river','The source sense includes printing on paper or cloth.')]);
P('printer','From print + agent suffix -er; it names a machine or, historically, a person who prints.',C('printer.s1','office technology','The printer jammed when the office tried to produce twenty copies of the report.','办公室试着打印二十份报告时，打印机卡纸了。','printer jammed','noun subject','The source entry’s main sense is a machine that puts text or images onto paper.'),M('The printer scanned the paper and returned only an empty sheet without producing an image.','The printer put the report text onto paper.','A printer produces text or images on paper; scanning alone is a different function.','meaning'),[Q(1,'What happened to the printer?','it jammed while making copies','it became a principality','it weighed a pound','A printer is a machine that puts images or text on paper.'),Q(1,'What was the office trying to produce?','twenty report copies','a glass prism','a royal title','The context specifies printed copies.'),Q(1,'Which device is a printer?','a machine that makes paper copies','a camera that only captures images','a postal code','The source sense names a text/image output machine.'),Q(1,'Which output can a printer produce?','a page with text or images','a spoken lecture only','a glass light spectrum','Printers put words or pictures onto paper.')]);
P('printing','From print + -ing; it names the technique or industry of reproducing text and images, or one impression/run of a book.',C('printing.s1','publishing','The second printing corrected the map labels that had been missing from the first run.','第二次印刷修正了第一版中漏掉的地图标签。','second printing','ordinal + noun','Printing can mean the process or a particular impression of a book.'),M('The second printing corrected the labels in the first impression before the first one existed.','The second printing corrected errors found in the first impression.','A later printing follows the first and can incorporate corrections.','meaning'),[Q(1,'What was corrected in the second printing?','missing map labels','a postal fee','a prism’s shape','A printing can mean a particular run of a book.'),Q(1,'What does printing name as an industry?','the process of reproducing text and images','a royal territory','a type of prison','Printing is a production technique.'),Q(1,'What is a second printing?','a later impression of the book','the first handwritten draft','a book’s subject index','The term can refer to a later production run.'),Q(1,'Which is an example of printing as a technique?','pressing inked type onto paper','reading a manuscript aloud','sealing a postcard','Printing reproduces words or images.')]);
P('printmaker','A compound of print + maker; it names an artist who creates original prints by techniques such as etching or woodcut.',C('printmaker.s1','visual arts','The printmaker carved a woodblock, inked it, and pulled a small edition by hand.','版画家刻好木版、上墨，再手工印制了一小批版画。','printmaker carved a woodblock','noun subject','A printmaker makes original art prints.'),M('The printmaker created an original etching by photocopying someone else’s finished poster.','The printmaker created an original etching by preparing and printing the plate.','A printmaker produces original prints through an art process, not merely copying a poster.','meaning'),[Q(1,'What did the printmaker carve?','a woodblock','a postal form','a prison wall','Printmakers use blocks or plates to make prints.'),Q(1,'What did the artist make?','a small edition of original prints','a handwritten schedule','a prince’s title','A printmaker creates original print artworks.'),Q(1,'Which activity fits printmaker?','etching a plate and printing it','repairing an office printer','sorting letters','The source sense includes etching and other art techniques.'),Q(1,'What is a printmaker?','an artist who creates original prints','a machine that prints pages','a person who frames photos only','The suffix maker marks the artist who makes prints.')]);
P('printmaking','A transparent compound of print + making; it names artistic processes such as relief, intaglio, and screen printing.',C('printmaking.s1','visual arts','The class explored printmaking by carving a relief block and pressing it onto paper.','课程通过刻制凸版并压印到纸上来探索版画创作。','explored printmaking','verb + object','Printmaking is the creation of artistic prints through specialized processes.'),M('The class studied printmaking by refusing to make, ink, or transfer any image.','The class studied printmaking by carving, inking, and transferring a design.','Printmaking is an art practice that creates images through a printing process.','meaning'),[Q(1,'What did students carve?','a relief block','a glass prism','a clay pot','Relief printing is one printmaking technique.'),Q(1,'What did they press onto paper?','the carved block','a royal seal only','a prison key','The example describes transferring an inked design.'),Q(1,'Which process is printmaking?','screen printing','postal sorting','pottery firing','The source sense lists screen printing as an artistic technique.'),Q(1,'What does printmaking produce?','artistic prints','only handwritten letters','a unit of power','Printmaking is the art of creating prints.')]);
P('prior','The adjective is from Latin prior “former, earlier,” comparative of an old form meaning “before”; the monastic noun comes from Latin prior “one who is before.”',[C('prior.s1','sequence','A prior agreement required both teams to share the laboratory after 6 p.m.','先前的协议要求两个团队在晚上六点后共用实验室。','prior agreement','adjective before noun','Prior means existing or happening before something else.'),C('prior.s2','importance','Because safety takes prior importance, the crew inspected the scaffolding first.','由于安全更为重要，工作人员先检查了脚手架。','prior importance','adjective + noun','Prior can mean more important or taking precedence.'),C('prior.s3','religion','The prior welcomed the visitors to the small monastery and explained its daily routine.','隐修院院长欢迎访客，并介绍了院里的日常安排。','the prior welcomed','noun subject','A prior is the head of a priory.')],M('The prior agreement was signed after the new policy it was supposed to precede.','The prior agreement was signed before the new policy.','Prior in the temporal sense means earlier.','meaning'),[Q(1,'When was the agreement made?','before the new policy','after the new policy','during a print run','Prior means earlier in time.'),Q(2,'What took prior importance?','safety','the schedule’s decoration','the postcard','Prior can describe something more important.'),Q(3,'Who welcomed the visitors?','the head of a small monastery','a junior prisoner','a printer','The noun prior names the head of a priory.'),Q(1,'Which phrase means an earlier experience?','prior experience','potential experience only','postwar experience','Prior is an adjective meaning earlier.')]);
P('prioritize','From priority + -ize, ultimately based on Latin prior “earlier”; it means rank by importance or give something precedence.',C('prioritize.s1','planning','The nurse prioritized patients by urgency before assigning rooms.','护士先按病情紧急程度排序，再分配病房。','prioritized patients by urgency','verb + object + by','This sense arranges tasks or people in order of importance.'),M('The nurse prioritized patients by placing the least urgent cases first regardless of medical need.','The nurse prioritized patients by treating the most urgent cases first.','Prioritize means order by importance; urgent cases should rank first here.','meaning'),[Q(1,'How did the nurse rank patients?','by medical urgency','by alphabetical order of their hometowns','by the color of their clothes','Prioritize means arrange in order of importance.'),Q(1,'Which task should a team prioritize?','a safety hazard that could injure someone','a decorative change with no deadline','a low-impact optional task','Priority should go to the most important concern.'),Q(1,'What does prioritize mean?','decide what should come first','delay every decision','print a list of names','The verb orders tasks by importance.'),Q(1,'What did the nurse do before assigning rooms?','ranked patients by urgency','discharged every patient','postdated the schedule','The context states the ordering step.')]);
P('priority','From Medieval Latin prioritas “the state of being before,” based on Latin prior “earlier.”',[C('priority.s1','planning','Finishing the safety review is our top priority before the equipment is switched on.','设备启动前完成安全检查是我们的首要任务。','top priority','adjective + noun','A priority is an important task that should be done first.'),C('priority.s2','right of way','Emergency vehicles have priority at the intersection when their warning lights are on.','警示灯亮起时，急救车辆在路口享有优先通行权。','have priority at','verb + noun + preposition','Priority can mean the right to be served or go before others.')],M('The safety review was our top priority, so we deliberately left it until every other task was done.','The safety review was our top priority, so we completed it before starting the equipment.','A top priority is handled before less important tasks.','meaning'),[Q(1,'What must be finished first?','the safety review','the equipment’s paint job','the postscript','A priority is something important that should be done first.'),Q(2,'Who has right of way at the intersection?','emergency vehicles with warning lights','every parked car','the postal worker only','Priority can be a right to proceed first.'),Q(1,'Which task is a priority?','a required safety check before startup','an optional decoration','a task with no deadline or consequence','Priority marks importance and urgency.'),Q(2,'What does priority mean for the ambulance?','it may go before others','it must wait behind every car','it can park indefinitely','The second sense is a right of precedence.')]);
P('prise','From Old French pris(er), “to take or seize,” related to Latin prehendere “to grasp”; the verb means force something open with leverage.',C('prise.s1','repair','She used a flat bar to prise the stuck lid off the paint tin.','她用扁撬棍把卡住的油漆罐盖撬开。','prise the lid off','verb + object + off','Prise means force an object open with a tool; British spelling.'),M('He prised the lid open by gluing it permanently shut.','He prised the lid open with a flat bar.','To prise open is to force something apart, often using leverage.','meaning'),[Q(1,'What tool did she use?','a flat bar','a postage stamp','a glass prism','A bar can provide leverage to prise something open.'),Q(1,'What did she prise off the tin?','the stuck lid','the paint inside','the postmark','The sentence says she forced the lid off.'),Q(1,'Which action means prise open?','lever a stuck cover apart','paint a cover','mail a cover','Prise means force open with a tool.'),Q(1,'Which spelling is the British verb form?','prise','prize only','prism','Prise is the British spelling for forcing something open.')]);
P('prism','From Greek prisma “something sawn,” from priein “to saw”; the optical solid was named for its cut geometric form.',C('prism.s1','optics','A glass prism split the white beam into a band of colors on the laboratory wall.','玻璃棱镜把白色光束分解成一条色带，投射在实验室墙上。','glass prism split','noun subject','A prism can separate white light or name the corresponding geometric solid.'),M('The prism combined the colors into white light by absorbing every wavelength.','The prism separated the white beam into its component colors.','A prism can refract and disperse white light into a spectrum.','meaning'),[Q(1,'What did the glass prism do to the beam?','split it into colors','turn it into sound','freeze it into ice','A prism can separate white light into colors.'),Q(1,'Where did the colors appear?','on the laboratory wall','inside a postal envelope','beneath the prison floor','The example states the wall was the projection surface.'),Q(1,'Which object is a prism?','a transparent solid that refracts light','a paper notice','a cooking pot','A prism is an optical or geometric solid.'),Q(1,'What is the geometric sense of prism?','a matching solid with polygonal ends','a flat circular sheet','a line of people','The word also names a geometric solid shape.')]);
P('prison','From Old French prison, from Latin prehensio “a taking or capture,” based on prehendere “to seize.”',[C('prison.s1','law','The court sent the convicted fraudster to prison for two years.','法院判处这名诈骗犯入狱两年。','sent the offender to prison','verb + object + preposition','A prison is a building where people convicted of crimes are held.'),C('prison.s2','figurative','For years, his fear of failure became a prison that kept him from trying anything new.','多年来，他对失败的恐惧成了牢笼，使他不敢尝试新事物。','became a prison','metaphorical complement','Prison can figuratively describe a situation that severely limits freedom.')],M('The court sent the offender to prison, where he was free to leave whenever he wished.','The court sent the offender to prison, where his freedom was restricted.','A prison is a place where people are confined.','meaning'),[Q(1,'Where was the offender sent?','a building where convicted people are confined','a university lecture hall','a pottery workshop','Prison is a place where criminals are held.'),Q(2,'What became a prison for him?','his fear of failure','a literal cell','his postal job','The figurative sense is a situation that severely restricts freedom.'),Q(1,'Which place is a prison?','a secure facility for people convicted of crimes','an open garden','a public library','The noun names a place of confinement.'),Q(2,'Why call fear a prison?','it prevented him from trying new things','it gave him a royal title','it helped him travel','The metaphor emphasizes severe limitation.')]);
P('prisoner','From prison + agent suffix -er; it names a person confined in prison or held by an enemy.',C('prisoner.s1','law','The prisoner wrote to her family while serving her sentence.','服刑期间，这名囚犯给家人写信。','prisoner wrote to her family','noun subject','A prisoner is someone kept in prison or held captive.'),M('The prisoner was free to leave the cell at any moment without permission.','The prisoner was kept in the cell under the terms of the sentence.','A prisoner is a person whose freedom is restricted by confinement.','meaning'),[Q(1,'Who wrote to her family?','a person serving a sentence','the prison building','a postal inspector','Prisoner names a person kept in prison.'),Q(1,'Which person could be a prisoner?','someone held by an enemy','a visitor leaving the gate','a prison architect only','The sense includes someone held captive.'),Q(1,'What does -er indicate in prisoner?','a person associated with imprisonment','a place to send a letter','a future event','The suffix forms a person noun from prison.'),Q(1,'Which statement matches the example?','she was confined while serving her sentence','she was managing the prison','she was free to leave at will','A prisoner is held in confinement.')]);
P('pristine','From Latin pristinus “former, original”; the sense of unspoiled purity preserves the idea of an original state.',[C('pristine.s1','environment','The remote lake remained pristine because no roads or factories reached its shore.','这座偏远湖泊仍保持原始纯净，因为湖岸没有公路或工厂。','remained pristine','linking verb + adjective','Pristine can mean in a pure natural state, not polluted or spoiled.'),C('pristine.s2','condition','The collector found a pristine first edition with no stains or torn pages.','收藏家找到了一本崭新的初版书，没有污渍或破页。','pristine first edition','adjective before noun','The adjective can also mean completely clean and undamaged.')],M('The lake was pristine despite the sewage pipe emptying into it every day.','The lake was pristine because no pollution or development reached it.','Pristine means unspoiled and pure, not contaminated.','meaning'),[Q(1,'Why was the lake pristine?','no roads or factories reached it','sewage entered it daily','it was covered in waste','Pristine in this sense means unpolluted and natural.'),Q(2,'What condition was the book in?','new and undamaged','stained and torn','missing its cover','Pristine can mean completely clean and without damage.'),Q(1,'Which site might remain pristine?','a remote shore with no pollution','a dumping ground','a heavily industrial harbor','The first describes a pure, unspoiled state.'),Q(2,'Choose a close meaning for pristine in the book example.','mint-condition','worn-out','contaminated','The second sense means new and immaculate.')]);
P('privacy','From private + -acy, a suffix forming an abstract state; private comes from Latin privatus “set apart, personal.”',[C('privacy.s1','personal data','The app asks for access only to data necessary for the service, protecting users’ privacy.','这款应用只请求服务所必需的数据访问权限，以保护用户隐私。','protecting users’ privacy','possessive noun','Privacy includes personal matters someone does not want others to know.'),C('privacy.s2','solitude','She closed the office door to have a little privacy while making the call.','她关上办公室门，以便打电话时有一点清静。','have a little privacy','noun complement','Privacy can also mean being alone and undisturbed.')],M('The app protected privacy by publishing every user’s private messages online.','The app protected privacy by limiting access to users’ personal information.','Protecting privacy means keeping personal matters from unwanted exposure.','meaning'),[Q(1,'What did the app protect?','users’ personal information','a printer cartridge','a royal principality','Privacy includes personal matters people do not want widely known.'),Q(2,'Why did she close the office door?','to be alone and undisturbed','to publish a message','to hold a public meeting','Privacy can mean solitude.'),Q(1,'Which action respects privacy?','limiting access to personal data','posting private messages publicly','sharing passwords','Privacy involves control over personal information.'),Q(2,'Choose a close meaning for privacy here.','seclusion','publicity','authority','She wanted to be undisturbed during the call.')]);
P('private','From Latin privatus “set apart, personal,” past participle of privare “deprive.”',[C('private.s1','ownership','The family keeps a private garden behind a locked gate.','这家人在锁着的门后有一座私人花园。','private garden','adjective before noun','Private means belonging to an individual or group, not the public.'),C('private.s2','confidentiality','The doctor promised that the conversation would remain private.','医生承诺谈话内容会保密。','remain private','linking verb + adjective','Private can mean secret or not intended for wide sharing.'),C('private.s3','institutions','Her daughter attends a private school funded by tuition rather than the government.','她女儿就读于一所靠学费而非政府拨款的私立学校。','private school','adjective before noun','Private can describe an institution run outside government.'),C('private.s4','military','The private carried supplies to the checkpoint before dawn.','天亮前，这名列兵把补给送到了检查站。','the private carried supplies','noun subject','Private is also the lowest rank of soldier.')],M('The private conversation was broadcast to the whole town without the speakers’ consent.','The private conversation was kept confidential and not shared publicly.','Private in this sense means not intended to be shared widely.','meaning'),[Q(1,'Whose garden was it?','the family’s, not the public’s','the government’s public park','a school classroom','Private can mean belonging to an individual or group.'),Q(2,'What did the doctor promise?','the conversation would stay confidential','the conversation would be printed','the patient would join the army','Private can mean not shared widely.'),Q(3,'How was the school funded?','by tuition rather than government','by a royal prize','by a prison sentence','Private describes a non-government-run institution.'),Q(4,'What rank did the soldier hold?','the lowest rank','a university professorship','a prince’s title','A private is the lowest military rank.')]);
P('privately','From private + adverb suffix -ly; it means secretly or in a personal, nonofficial capacity.',[C('privately.s1','confidentiality','The two negotiators spoke privately before presenting their proposal to the larger group.','两位谈判者先私下交谈，再向更大的团队提交方案。','spoke privately','adverb modifying verb','This sense means without other people knowing.'),C('privately.s2','ownership','The researcher funded the small archive privately rather than through her university.','研究人员以私人身份而非通过大学资助了这个小档案馆。','funded privately','adverb modifying verb','Privately can mean using personal resources, not as part of an official job.')],M('They spoke privately by announcing every detail over the public loudspeaker.','They spoke privately in a room where others could not hear.','Privately means away from public knowledge or attention.','meaning'),[Q(1,'When did the negotiators speak?','out of earshot of the larger group','on the public loudspeaker','during the final presentation','Privately means without others knowing.'),Q(2,'How did the researcher support the archive?','with personal resources','through an official university grant','with a prison sentence','The second sense is in a personal, nonofficial capacity.'),Q(1,'Which conversation is private?','one held confidentially between two people','one broadcast to the crowd','one printed on a poster','The adverb describes secret or confidential action.'),Q(2,'What does privately funded suggest?','personal rather than institutional support','funded by the government','funded through tuition only','Privately can mean using personal resources.')]);
P('privatize','From private + -ize, ultimately Latin privatus; the verb means transfer a state-owned activity or asset to private ownership.',C('privatize.s1','public policy','The government voted to privatize the rail operator by selling it to private investors.','政府投票决定把铁路运营商出售给私人投资者，实现私有化。','privatize the rail operator','verb + object','Privatize means transfer a state-owned service or business to private ownership.'),M('The state privatized the rail operator by taking it away from investors and placing it under full government control.','The state privatized the rail operator by selling it to private investors.','Privatization transfers an activity from state to private ownership.','meaning'),[Q(1,'What happened to the rail operator?','it was sold to private investors','it was brought under full state ownership','it was turned into a principality','To privatize is to transfer a state-owned activity to private owners.'),Q(1,'Which action privatizes a company?','selling a government-owned firm to private buyers','buying a private firm for the state','closing a public road','The verb means move an activity into private ownership.'),Q(1,'Who would own the operator after privatization?','private investors','the government alone','the railway passengers equally by definition','Privatize transfers ownership to private companies or people.'),Q(1,'What does -ize form in privatize?','a verb meaning make or render private','a plural noun','a past participle','The suffix forms the action verb.')]);
P('privilege','From Latin privilegium, “a law for an individual,” formed from privus “private” + lex “law.”',[C('privilege.s1','social rights','The scholarship gave first-generation students access to labs, a privilege previously limited to a few.','这项奖学金让第一代大学生得以使用实验室；此前只有少数人享有这种特殊权益。','gave access as a privilege','noun complement','A privilege is a right or advantage available only to some.'),C('privilege.s2','gratitude','It was a privilege to hear the elder describe her community’s history.','能听这位长者讲述社群历史，实属荣幸。','a privilege to hear','noun + infinitive','A privilege can be an opportunity someone is pleased and proud to have.'),C('privilege.s3','advantages','The program should not privilege wealthy applicants over equally qualified students.','该项目不应让富裕申请者比同样合格的学生享有优待。','privilege wealthy applicants','verb + object','As a verb, privilege means give a group a special advantage.')],M('The scholarship was a privilege open equally to every person without any special access or advantage.','The scholarship gave a particular group an advantage not previously available to them.','A privilege is a special right or advantage granted to some.','meaning'),[Q(1,'Who gained access to the labs?','first-generation students through the scholarship','only the laboratory owners','the postal service','Privilege can mean an advantage given to a particular group.'),Q(2,'Why did she call hearing the story a privilege?','she felt honored to be allowed to hear it','she was forced to leave','she had to pay a penalty','A privilege can be an opportunity one is pleased to have.'),Q(3,'What should the program avoid doing?','giving wealthy applicants a special advantage','treating applicants equally','using clear criteria','To privilege a group is to give it an advantage.'),Q(1,'Which is a privilege?','access granted only to selected students','a requirement imposed on everyone','a postal code','The source sense is a special right or benefit.')]);
P('privileged','From privilege + -ed; it describes someone who benefits from special advantages such as wealth, rank, or restricted access.',C('privileged.s1','society','The privileged students had access to private tutors and well-equipped laboratories.','享有特权的学生可以使用私人辅导和设备齐全的实验室。','privileged students','adjective before noun','Privileged means benefiting from advantages many people do not have.'),M('The privileged students had fewer resources and opportunities than everyone else.','The privileged students had special resources and opportunities unavailable to many others.','Privileged describes having advantages, not being deprived of them.','meaning'),[Q(1,'What advantages did the students have?','private tutors and advanced labs','no access to instruction','a prison sentence','Privileged means benefiting from special advantages.'),Q(1,'Which person is privileged in this sense?','someone with resources unavailable to most people','someone denied every opportunity','someone delivering a postcard','The adjective describes relative advantage.'),Q(1,'What does privileged modify?','students','tutors','laboratories','It describes the students who have special access.'),Q(1,'Choose a close paraphrase of privileged.','advantaged','dispossessed','ordinary by necessity','Privileged people benefit from wealth, rank, or access.')]);
P('prize','From Old French pris “value, reward,” from Latin pretium “worth”; senses include an award, something valued, and the verb “cherish.”',[C('prize.s1','competition','The winning team received a prize for its design of the community garden.','获胜团队因社区花园设计获得了奖品。','received a prize','verb + object','A prize is awarded to a winner or someone who performs well.'),C('prize.s2','description','The museum displayed a prize specimen from its collection of rare minerals.','博物馆展出了一件珍贵的稀有矿物标本。','prize specimen','adjective before noun','Prize as an adjective means especially valuable or award-worthy.'),C('prize.s3','value','She prizes the handwritten letters because they were sent by her grandmother.','她珍视这些手写信，因为它们是祖母寄来的。','prizes the letters','verb + object','The verb means consider something highly valuable.')],M('The student won a prize for the project but immediately treated it as worthless trash.','The student won a prize for the project and displayed it with pride.','A prize is an award, usually treated as something of value.','meaning'),[Q(1,'What did the winning team receive?','an award','a postal position','a cooking pot','Prize as a noun means an award for a winner.'),Q(2,'What kind of specimen did the museum show?','a particularly valuable one','a broken and useless one','a mass-produced poster','Prize as an adjective means valuable or special.'),Q(3,'Why does she prize the letters?','they are precious to her','they are made of glass','they are a prison sentence','The verb means value or cherish.'),Q(1,'Which item is a prize?','a medal given to a contest winner','a routine invoice','a safety procedure','A prize is awarded for achievement.')]);
P('prized','From the past participle of prize, “value highly”; as an adjective it means especially cherished or important.',C('prized.s1','collecting','The prized first edition remained in a locked case, away from sunlight and handling.','这本备受珍视的初版书一直锁在展柜里，避免日晒和触摸。','prized first edition','adjective before noun','Prized describes something considered especially valuable.'),M('The prized manuscript was thrown out because nobody considered it valuable.','The prized manuscript was carefully protected because it was highly valued.','Prized means especially valued or cherished.','meaning'),[Q(1,'Why was the first edition protected?','it was highly valued','it was an ordinary disposable copy','it was a printer','Prized means considered especially valuable.'),Q(1,'Which object might be prized?','a rare family heirloom','a broken label no one needs','a blank receipt','The adjective describes something cherished.'),Q(1,'What did the case protect it from?','sunlight and handling','the post office','a prizefight','The context names the hazards.'),Q(1,'Choose a close meaning for prized.','treasured','discarded','common','Prized means valued highly.')]);
P('prizefight','A compound of prize + fight; it names a professional boxing contest in which the winner receives a prize or purse.',C('prizefight.s1','sports','The two professionals trained for months before their prizefight at the city arena.','两名职业拳手在市体育馆的奖金拳赛前训练了数月。','prizefight at the arena','noun + prepositional phrase','A prizefight is a public professional boxing match with a prize for the winner.'),M('The prizefight was a chess match with no boxers and no award for the winner.','The prizefight was a professional boxing match with a purse for the winner.','A prizefight is a boxing contest with a prize or purse.','meaning'),[Q(1,'What kind of contest was scheduled?','professional boxing','a spelling bee','a pottery exhibition','Prizefight names a boxing match.'),Q(1,'What could the winner receive?','a prize or purse','a postmaster’s uniform','a prison term','The prize is part of the term’s meaning.'),Q(1,'Where did it take place?','the city arena','a private garden','a laboratory wall','The example locates the boxing event at the arena.'),Q(1,'Which event is a prizefight?','a public pro boxing contest with a purse','a silent debate','a chess lesson','The source sense is professional boxing for a prize.')]);
P('pro-form','From pro- “in place of” + form; in grammar, a pro-form is a word that stands in for another word or phrase.',C('pro-form.s1','grammar','In “Maya bought a red bag, and Leo bought one too,” one is a pro-form for bag.','在“Maya买了一个红包，Leo也买了一个”中，one代替bag。','one is a pro-form for bag','subject complement','A pro-form substitutes for another linguistic expression.'),M('In “Maya bought a bag and Leo bought one,” one introduces a new unrelated object rather than replacing bag.','In that sentence, one stands in for the noun bag.','A pro-form replaces or stands in for another expression.','grammar'),[Q(1,'What does one replace in the example?','bag','Maya','bought','A pro-form stands in for another word, here bag.'),Q(1,'What is a pro-form?','a word that substitutes for another expression','a punctuation mark','a type of postage','The grammar sense is a substitute form.'),Q(1,'Which word is a pro-form in “I need a pen; do you have one?”','one','need','you','One replaces pen.'),Q(1,'What does pro- mean in this term?','in place of','before','without','The prefix indicates substitution.')]);
P('proactive','From pro- “forward, beforehand” + active, from Latin agere “do”; proactive action anticipates a situation instead of merely reacting.',C('proactive.s1','management','The team took a proactive approach by replacing worn cables before any machine failed.','团队采取了主动措施，在机器故障前更换磨损的电缆。','proactive approach','adjective before noun','Proactive means acting in advance to influence or prevent a situation.'),M('The team was proactive by waiting for every machine to fail before replacing anything.','The team was proactive by replacing worn cables before failures occurred.','Proactive action anticipates problems rather than waiting to react.','meaning'),[Q(1,'When did the team replace the cables?','before a machine failed','after every machine broke','after the factory closed','Proactive means taking action in advance.'),Q(1,'Which response is proactive?','checking equipment before a failure','repairing only after a breakdown','ignoring a warning','The adjective describes anticipating and preventing problems.'),Q(1,'What does pro- contribute to proactive?','forward or beforehand','against','behind','Pro- can mean forward or before.'),Q(1,'Why was the approach proactive?','it prevented a problem before it happened','it recorded a past problem only','it delayed maintenance indefinitely','The context describes advance prevention.')]);
P('probability','From Medieval Latin probabilitas, from probabilis “provable or likely,” based on Latin probare “test, prove.”',C('probability.s1','statistics','The probability of drawing a red card from a standard deck is one half.','从一副标准扑克牌中抽到红牌的概率是二分之一。','probability of drawing','of-phrase','Probability is the chance that an event will happen or a statement be true.'),M('The probability was one half, meaning the event was certain to happen every time.','The probability was one half, meaning the event had an equal chance of happening or not.','A probability of one half indicates equal likelihood, not certainty.','measurement'),[Q(1,'What is the probability of drawing a red card?','one half','zero','one hundred times','A standard deck has equal numbers of red and black cards.'),Q(1,'What does probability measure?','the chance an event happens','the weight of a card','the printer’s speed','Probability quantifies likelihood.'),Q(1,'What does a probability of 1 mean?','the event is certain in the model','the event is impossible','the event has no chance','Probability ranges from impossibility to certainty.'),Q(1,'Which field commonly uses probability?','statistics','pottery','postal delivery','Probability is a quantitative measure of chance.')]);
P('probable','From Latin probabilis “worthy of approval, likely,” from probare “test, prove.”',[C('probable.s1','forecasting','Rain is probable this evening, but the forecast does not guarantee it.','今晚很可能下雨，但天气预报并不能保证。','rain is probable','predicate adjective','Probable means expected or more likely than not.'),C('probable.s2','selection','The probable finalists were announced before the judges made their final decision.','评委作出最终决定前，较有希望入围的选手名单已经公布。','probable finalists','adjective before noun','Probable can describe someone likely to be selected or become something.')],M('Rain is probable tonight, so the forecast says it is impossible under every condition.','Rain is probable tonight, meaning it is more likely than not but not certain.','Probable means likely, not guaranteed or impossible.','meaning'),[Q(1,'Does the forecast guarantee rain?','No; it says rain is likely, not certain.','Yes, probable means certain.','No; probable means impossible.','Probable indicates a strong chance short of certainty.'),Q(2,'Who were the probable finalists?','people likely to be selected','people already disqualified','the judges themselves','This sense refers to likely candidates.'),Q(1,'Which event is probable?','one expected to happen but not guaranteed','one that cannot happen','one already completed','Probable means more likely than not.'),Q(2,'What does probable modify in “probable winner”?','winner','probability','announced','The adjective describes someone likely to win.')]);
P('probably','From probable + adverb suffix -ly; it means with a high chance but less than certainty.',C('probably.s1','inference','The train will probably arrive late because snow has slowed the line.','由于降雪使线路变慢，火车很可能会晚点。','will probably arrive','adverb modifying verb','Probably signals likely but not certain.'),M('The train will probably arrive late, which means the timetable guarantees it will be on time.','The train will probably arrive late, though a delay is not certain.','Probably expresses likelihood rather than a guarantee.','meaning'),[Q(1,'Why will the train probably be late?','snow has slowed the line','the line is closed forever','the train has already arrived','The context gives snow as the reason for likely delay.'),Q(1,'What does probably mean?','likely but not certain','impossible','absolutely guaranteed','The adverb marks a high chance short of certainty.'),Q(1,'Which word does probably modify?','arrive','train','snow','It modifies the verb phrase will arrive.'),Q(1,'Which statement uses probably correctly?','She will probably call, but it is not certain.','She probably is certain never to call.','Probably means definitely impossible.','Probably indicates likelihood, not certainty.')]);
P('probation','From Latin probationem “a testing or proof,” from probare “test”; legal and employment senses involve a period of assessment.',[C('probation.s1','law','The judge placed the first-time offender on probation instead of sending him to prison.','法官让这名初犯接受缓刑监管，而没有把他送进监狱。','placed the offender on probation','verb + object + preposition','Legal probation lets a person remain in the community under conditions.'),C('probation.s2','employment','New hires spend three months on probation while managers assess their work.','新员工有三个月试用期，经理会在这段时间评估其工作表现。','on probation','fixed phrase','Probation can be a trial period for a worker or student.')],M('The new hire completed probation without being assessed and before the trial period began.','The new hire completed probation after managers assessed the work during the trial period.','Probation is a period of assessment, not a period before assessment begins.','meaning'),[Q(1,'What did the judge order?','a period of supervised release in the community','an automatic life sentence','a prizefight','Legal probation allows someone to remain in the community under conditions.'),Q(2,'What happens during a new hire’s probation?','managers assess the employee’s work','the employee becomes a judge','the employee is sent to prison','Employment probation is a trial period.'),Q(1,'What does probation mean in court?','a conditional period outside prison','a final appeal','a royal privilege','The court sense is supervised release.'),Q(2,'How long was the trial period at work?','three months','three years','one week','The example specifies three months.')]);
P('probe','From Latin probare “to test or prove,” through French probe; it can mean investigate or a tool/device used for examination.',[C('probe.s1','investigation','Reporters probed the contractor’s records to find out how the public funds were spent.','记者调查承包商的记录，查明公共资金的去向。','probed the records','verb + object','The verb means examine or question carefully to uncover facts.'),C('probe.s2','science','The space probe sent measurements from the icy moon back to Earth.','太空探测器把来自冰卫星的测量数据传回地球。','space probe sent measurements','noun subject','A probe is a device sent or used to examine something.')],M('The reporters probed the records by refusing to examine or ask about them.','The reporters probed the records by examining them closely and asking questions.','To probe is to investigate deeply, not avoid inquiry.','meaning'),[Q(1,'What did the reporters investigate?','the contractor’s records','a pottery wheel','the icy moon directly','Probe as a verb means examine closely for facts.'),Q(2,'What sent measurements to Earth?','a space probe','a postal worker','a private school','Probe can name a device used for exploration.'),Q(1,'Which action is probing?','asking detailed questions about hidden facts','ignoring the documents','printing a poster','The verb means investigate deeply.'),Q(2,'What is a space probe?','a device sent to explore or examine','a prison building','a rule of conduct','The noun is a scientific exploration device.')]);
P('probity','From Latin probitas “uprightness, honesty,” from probus “good, upright.”',[C('probity.s1','ethics','The board selected her for the audit because colleagues trusted her probity.','董事会选她负责审计，因为同事信任她的正直品格。','trusted her probity','verb + object','Probity is complete honesty and moral integrity.'),C('probity.s2','public service','The watchdog praised the treasurer’s probity in handling public funds.','监督机构称赞财务主管处理公共资金时廉洁奉公。','probity in handling','of-phrase','The word can emphasize honesty in money and public duties.')],M('The treasurer showed probity by secretly diverting public funds into a personal account.','The treasurer showed probity by keeping public funds accurately accounted for.','Probity means honesty and integrity, especially in public or financial duties.','meaning'),[Q(1,'Why did colleagues trust her?','she had a reputation for honesty','she hid every audit record','she altered the accounts','Probity is moral honesty.'),Q(2,'What did the watchdog praise?','integrity in handling public money','a postal schedule','a printer repair','The second sense emphasizes public and financial honesty.'),Q(1,'Which person shows probity?','an official who reports every transaction accurately','an official who diverts funds secretly','an official who destroys receipts','Probity means uprightness and honesty.'),Q(2,'Choose a close meaning for probity.','integrity','deceit','carelessness','The word names complete honesty.')]);
P('problem','From Latin problema and Greek problēma “something put forward,” from proballein “throw forward.”',[C('problem.s1','daily life','The broken lift became a serious problem for residents who could not use the stairs.','电梯坏了，这对无法走楼梯的居民来说成了严重问题。','became a serious problem','linking verb + complement','A problem is a difficult situation needing attention or a solution.'),C('problem.s2','education','The final problem asked students to calculate how much paint the room would need.','最后一道题要求学生计算房间需要多少油漆。','problem asked students','noun subject','Problem can also mean a question or exercise that must be solved.')],M('The broken lift was no problem for residents because it prevented anyone from reaching their apartments.','The broken lift was a problem because it kept residents from reaching their apartments.','A problem is a difficulty that needs attention, not a helpful feature.','meaning'),[Q(1,'Why was the broken lift a problem?','residents could not use it to reach their homes','it made the stairs unnecessary','it painted the room','A problem is a difficult situation needing a solution.'),Q(2,'What did the final problem ask students to do?','calculate the needed paint','repair the lift','write a prayer','Problem can mean an exercise requiring an answer.'),Q(1,'Which is a problem?','a leak that damages the ceiling','a working elevator','a solved exercise','A problem is a difficulty or trouble.'),Q(2,'Which class might assign a problem?','mathematics','postal delivery','royal ceremony','The sense includes a question to be solved.')]);
P('problematic','From problem + -atic, ultimately from Greek problēma; the adjective describes something involving difficulty, uncertainty, or moral concern.',C('problematic.s1','policy','The plan is problematic because it relies on data that the researchers have not verified.','这项计划有问题，因为它依赖研究人员尚未核实的数据。','plan is problematic','linking verb + adjective','Problematic signals difficulties or uncertainties.'),M('The plan was problematic because every figure had been independently verified and no uncertainty remained.','The plan was problematic because several key figures remained unverified.','Problematic means involving difficulties or uncertainty.','meaning'),[Q(1,'Why is the plan problematic?','some data are unverified','all uncertainty has been removed','the researchers have finished their work','The adjective describes unresolved difficulty.'),Q(1,'Which choice is problematic?','one that depends on disputed evidence','one supported by verified facts','one with no possible objection','Problematic means involving difficulties or concerns.'),Q(1,'What does problematic modify?','plan','data','researchers','It is the predicate adjective describing the plan.'),Q(1,'Choose a close meaning for problematic.','troublesome','certainly flawless','irrelevant','Problematic means involving problems or uncertainty.')]);
P('proboscidean','From Proboscidea, the mammalian order name based on Greek proboskis “trunk”; the adjective means belonging to that order.',C('proboscidean.s1','zoology','The museum labeled the fossil tooth as proboscidean because it came from an ancient elephant relative.','博物馆把这颗化石牙齿标为长鼻目动物的，因为它来自古代象类近亲。','proboscidean tooth','adjective before noun','Proboscidean relates to the order that includes elephants.'),M('The proboscidean tooth came from a fish with no trunked mammal relatives.','The proboscidean tooth came from an ancient elephant relative.','Proboscidean refers to elephants and related mammals.','meaning'),[Q(1,'What group did the fossil belong to?','elephants and their relatives','modern fish','insects only','Proboscideans are members of the elephant order.'),Q(1,'Why was the tooth labeled proboscidean?','it came from an ancient elephant relative','it came from a flowering plant','it was made of glass','The adjective marks membership in Proboscidea.'),Q(1,'Which animal is proboscidean?','an elephant','a prawn','a frog','Elephants are living members of the order.'),Q(1,'What does the ending -ean contribute here?','belonging or relating to a group','a plural verb','a measurement','Proboscidean means of or relating to Proboscidea.')]);
P('proboscis','From Latin proboscis and Greek proboskis “elephant’s trunk,” a word for an elongated snout or sucking mouthpart.',C('proboscis.s1','biology','The butterfly uncoiled its proboscis and drank nectar from the flower.','蝴蝶伸展开卷曲的口器，从花中吸取花蜜。','uncoiled its proboscis','verb + object','A proboscis can be a long snout or an insect’s extended sucking mouthpart.'),M('The butterfly used its proboscis to chew leaves with a set of broad molars.','The butterfly used its proboscis to sip nectar from the flower.','A butterfly’s proboscis is a tube-like mouthpart for sucking, not chewing.','meaning'),[Q(1,'What did the butterfly do with its proboscis?','sipped nectar','chewed leaves with molars','carried a parcel','A butterfly uses its proboscis to suck nectar.'),Q(1,'What is an insect proboscis?','an extended sucking mouthpart','a wing joint','a pollen grain','The source sense describes an elongated mouth used for sucking.'),Q(1,'Which animal may have a trunk-like proboscis?','an elephant','a printer','a pram','Proboscis can mean an elongated snout or trunk.'),Q(1,'What does uncoiled suggest about the butterfly’s proboscis?','it had been curled before extending','it was a flat wing','it was a hard tooth','The example says the mouthpart unrolled to feed.')]);
P('procedural','From procedure + -al, ultimately Latin procedere “go forward”; the adjective concerns fixed steps in an activity.',C('procedural.s1','law','The appeal was dismissed on procedural grounds because the filing arrived after the deadline.','上诉因程序问题被驳回，因为文件超过期限才提交。','procedural grounds','adjective + noun','Procedural relates to the formal steps used to carry out an action.'),M('The case was dismissed on procedural grounds even though every required step and deadline had been followed.','The case was dismissed on procedural grounds because a required filing step was missed.','Procedural concerns whether the required process was followed.','meaning'),[Q(1,'Why was the appeal dismissed?','the filing missed the deadline','the postal code was correct','the defendant won a prize','Procedural grounds concern required steps and rules.'),Q(1,'What does procedural describe?','the formal steps in a process','a person’s moral character','a type of elephant','The adjective relates to procedure.'),Q(1,'Which issue is procedural?','whether a form was filed on time','whether the argument is popular','whether a machine has enough power','A deadline is part of a formal procedure.'),Q(1,'What does a procedural review check?','whether rules and steps were followed','the court’s paint color','the size of a prism','Procedural concerns the process itself.')]);
P('procedure','From Old French procédure, from Latin procedere “go forward,” formed from pro- “forward” + cedere “go.”',[C('procedure.s1','administration','Follow the return procedure and attach the receipt before mailing the package.','请按退货流程办理，并在寄出包裹前附上收据。','follow the return procedure','verb + object','A procedure is an established series of official steps.'),C('procedure.s2','medicine','The surgeon explained each step of the procedure before the patient signed the consent form.','患者签署同意书前，外科医生解释了手术的每个步骤。','steps of the procedure','of-phrase','In medicine, a procedure is an operation or treatment with set steps.')],M('The hospital began the procedure without explaining any steps or obtaining consent.','The hospital explained the procedure and obtained consent before starting.','A medical procedure has defined steps and should be explained before it begins.','meaning'),[Q(1,'What should the customer follow?','the established return steps','the prisoner’s sentence','the museum’s prize list','A procedure is a set way of doing something.'),Q(2,'What did the surgeon explain?','the steps of the treatment','the postage rate','the professor’s rank','Procedure can mean a medical operation or treatment.'),Q(1,'Which is an official procedure?','steps for submitting a permit application','a private thought','an elephant’s trunk','The first sense involves formal steps.'),Q(2,'What kind of procedure did the surgeon discuss?','a medical operation or treatment','a postal route','a classroom exercise','The medical sense has defined treatment steps.')]);
P('proceed','From Latin procedere “go forward,” formed from pro- “forward” + cedere “go.”',[C('proceed.s1','activity','Once everyone had signed the consent form, the nurse proceeded with the examination.','所有人签完同意书后，护士继续进行检查。','proceeded with the examination','verb + with','Proceed means continue after a pause or decision.'),C('proceed.s2','movement','Visitors should proceed along the marked path to the viewing platform.','访客应沿着标记好的小路前往观景台。','proceed along the path','verb + along','The verb can mean move in a particular direction.'),C('proceed.s3','law','The company decided to proceed against the contractor for breach of contract.','公司决定就违约问题对承包商提起诉讼。','proceed against the contractor','formal legal phrase','In legal use, proceed can mean start or continue an action.')],M('The nurse proceeded with the examination before anyone signed the required consent form.','The nurse proceeded with the examination after the required consent form was signed.','Proceed means continue, but the context requires consent first.','meaning'),[Q(1,'When did the nurse continue the examination?','after the consent form was signed','before anyone considered consent','after leaving the clinic','Proceed can mean continue after a decision or pause.'),Q(2,'Where should visitors move?','along the marked path','into a closed area','back to the prison','Proceed can mean move in a direction.'),Q(3,'What legal action did the company take?','it pursued a claim against the contractor','it mailed a postcard','it ended the contract by prizefight','The legal sense means start or continue proceedings.'),Q(1,'Which phrase means continue with an activity?','proceed with the examination','prioritize the examination','print the examination','Proceed with is a standard construction.')]);
P('proceeding','From proceed + -ing; as a noun, it means formal steps or events, and in “proceedings” it can mean a conference’s published papers.',[C('proceeding.s1','legal','The court proceeding was postponed until both sides submitted their evidence.','双方提交证据前，法庭程序被延期。','court proceeding','adjective + noun','A proceeding is an action or step in a formal process.'),C('proceeding.s2','academic publishing','The conference proceedings included the papers presented during the robotics symposium.','会议论文集收录了机器人研讨会上宣读的论文。','conference proceedings','plural noun','Proceedings in this sense are the written reports of a conference.')],M('The conference proceedings contained no reports or papers from the conference.','The conference proceedings collected the papers presented at the meeting.','Conference proceedings are written records or papers from an event.','meaning'),[Q(1,'What was postponed?','a formal court process','the manufacture of a printer','the prairie','Proceeding can refer to a formal process.'),Q(2,'What did the conference proceedings contain?','papers presented at the symposium','a postal fee','a prison sentence','Conference proceedings are written reports of a meeting.'),Q(1,'Which event is a proceeding?','a formal hearing','a private lunch only','a prism','The noun can name a step or action in a formal process.'),Q(2,'Why is proceedings plural here?','it names the collected conference papers','it refers to one procedure only','it is a verb form','The published collection is conventionally called proceedings.')]);
P('proceeds','From proceed, Latin procedere “go forward”; the noun proceeds means money resulting from a sale or fundraising event.',C('proceeds.s1','finance','The proceeds from the charity auction paid for new books at the neighborhood library.','慈善拍卖所得用于为社区图书馆购买新书。','proceeds from the auction','noun + from-phrase','Proceeds are funds gained from a sale or event.'),M('The auction’s proceeds were the money bidders had to pay before the event began.','The auction’s proceeds were the money raised by selling the items.','Proceeds are money gained from the event, not advance payments to participate.','meaning'),[Q(1,'What paid for the library books?','money raised by the auction','the printer’s electricity','the auction’s postage stamps','Proceeds are funds gained from an event.'),Q(1,'Where did the proceeds come from?','the charity auction','a prison cell','a science experiment','The phrase identifies the source of the funds.'),Q(1,'Which amount is proceeds?','money earned by selling tickets','the cost to print the tickets','the auction’s schedule','Proceeds are money gained from a sale or event.'),Q(1,'What did the proceeds support?','buying books','building a prison','making a glass prism','The context states the funds supported the library.')]);
P('process','From Latin processus “a going forward,” from procedere; it names a sequence, an industrial method, or treating something by steps.',[C('process.s1','change','Learning a new language is a gradual process that takes regular practice.','学习一门新语言是一个需要持续练习的渐进过程。','gradual process','adjective before noun','A process is a series of events leading to a result.'),C('process.s2','manufacturing','The factory uses a cold process to shape the plastic into durable panels.','工厂用冷加工法把塑料制成耐用板材。','cold process','adjective + noun','A process can be an industrial method of making or changing something.'),C('process.s3','administration','The office will process the application within five working days.','办公室将在五个工作日内处理这份申请。','process the application','verb + object','As a verb, process means handle material, data, or an application by steps.')],M('The office processed the application by leaving it untouched in an inbox forever.','The office processed the application by checking its details and entering them into the system.','To process an application is to handle it through a set of steps.','meaning'),[Q(1,'What kind of thing is learning a language?','a sequence of stages','a single instant','a postal code','A process is a series of things leading to a result.'),Q(2,'What did the factory use to shape plastic?','a cold manufacturing method','a court proceeding','a prizefight','Process can name an industrial method.'),Q(3,'What will the office do to the application?','handle it through administrative steps','mail it without reading','turn it into a product','Process as a verb means handle something by steps.'),Q(1,'Which activity is a process?','a sequence of stages that leads to an outcome','a single unrelated fact','a royal title','The noun sense describes a series of events.')]);
P('processing','From process + -ing; the noun refers to a series of operations that prepares food, information, or a request for use.',C('processing.s1','technology','The scanner’s processing of each image took only a few seconds.','扫描仪处理每张图像只需几秒钟。','processing of each image','of-phrase','Processing prepares material or information through operations.'),M('The image processing left the files unchanged because no operation was performed.','The image processing adjusted the files’ contrast and removed noise.','Processing involves operations that treat or prepare information.','meaning'),[Q(1,'What did the scanner process?','each image','a principality','a prison sentence','Processing can involve preparing information for use.'),Q(1,'How long did each image take?','a few seconds','several years','one pound','The example gives a short processing time.'),Q(1,'Which activity is processing?','sorting and preparing a request','leaving every request untouched','mailing a blank envelope','Processing involves a series of operations.'),Q(1,'What does processing do to raw information?','treats it through steps','turns it into a royal title','prays over it','The source sense is a series of operations to prepare information.')]);
P('procession','From Latin processio “a going forward,” from procedere; it can mean a ceremonial line or a series of successive events.',[C('procession.s1','ceremony','A procession of lanterns moved slowly through the old town during the festival.','节庆期间，一列灯笼缓缓穿过老城区。','procession of lanterns','of-phrase','A procession is a line moving forward, often for a ceremony.'),C('procession.s2','sequence','A procession of unexpected delays kept the research team from reaching the site.','一连串意外延误让研究团队无法抵达现场。','procession of delays','of-phrase','The figurative sense is a succession of people or events.')],M('The procession moved through town as each lantern remained alone at home.','The procession moved through town as the lantern-bearers walked together.','A procession is a group or line moving forward together.','meaning'),[Q(1,'What moved through the old town?','a ceremonial line of lanterns','a single stationary poster','the conference papers','A procession is a line moving together.'),Q(2,'What kept the team from the site?','a series of unexpected delays','one successful arrival','a glass prism','Procession can mean successive events.'),Q(1,'Which event might include a procession?','a festival parade','a private email','a math problem','The literal sense often describes a ceremony.'),Q(2,'What does “a procession of delays” mean?','one delay after another','a single quick success','a line of vehicles in a parade only','The figurative sense describes a series.')]);
P('processor','From process + agent suffix -or; it names a computer chip that executes commands or a machine/person that processes materials.',C('processor.s1','computing','The laptop’s processor handled the video edit without slowing the other programs.','笔记本电脑的处理器处理视频剪辑时没有拖慢其他程序。','processor handled the edit','noun subject','The central processor is the chip that carries out computer commands.'),M('The processor stored the laptop’s documents but could not execute any commands.','The processor executed the laptop’s commands while programs were running.','A computer processor carries out instructions; storage is a different function.','meaning'),[Q(1,'What handled the video edit?','the computer’s processor','a printed poster','the postal service','A processor is the chip that executes commands.'),Q(1,'What did it do without?','slowing other programs','printing the file on cloth','sending mail','The sentence describes its performance.'),Q(2,'Which is an industrial processor?','a machine that turns raw grain into flour','a computer chip only','a court hearing','The broader source sense includes machines that change materials.'),Q(1,'What does a central processor execute?','computer commands','postage payments','prison sentences','It carries out instructions in a computer.')]);
P('proclaim','From Latin proclamare “cry out, announce publicly,” formed from pro- “forth” + clamare “call.”',[C('proclaim.s1','announcements','The mayor proclaimed a day of mourning after the city’s founder died.','城市创始人去世后，市长宣布设立哀悼日。','proclaimed a day','verb + object','To proclaim is to announce something officially and publicly.'),C('proclaim.s2','evidence','The muddy footprints proclaim that someone entered the garden during the night.','泥脚印表明有人夜间进入了花园。','footprints proclaim','subject + verb + that-clause','The verb can mean show a fact clearly.')],M('The mayor proclaimed the new holiday by keeping the decision secret from everyone.','The mayor proclaimed the new holiday in a public announcement.','To proclaim is to make an official statement publicly.','meaning'),[Q(1,'What did the mayor announce?','a day of mourning','a cooking recipe','a prizefight','Proclaim can mean announce officially.'),Q(2,'What do the footprints show?','someone entered the garden','no one was there','the garden was a prison','Proclaim can mean reveal a fact clearly.'),Q(1,'Which act is to proclaim?','make a public official announcement','write a private note and hide it','walk through a procession','The first sense is formal public announcement.'),Q(2,'What does “the evidence proclaims” mean?','the evidence clearly shows','the evidence conceals','the evidence mails','The second sense is to show something openly.')]);
P('proclivity','From Latin proclivitas “a slope or inclination,” from proclivis “sloping forward/downhill.”',C('proclivity.s1','behavior','He has a proclivity for checking every door twice before leaving the house.','他有出门前把每扇门都检查两遍的习惯倾向。','proclivity for checking','noun + for','A proclivity is a tendency toward a particular behavior.'),M('Her proclivity for punctuality meant she consistently arrived several hours late.','Her proclivity for punctuality meant she regularly arrived on time.','A proclivity is a tendency; punctuality means being on time.','meaning'),[Q(1,'What habit does he tend to follow?','checking doors twice','leaving doors unlocked','printing every page','Proclivity means a tendency toward a behavior.'),Q(1,'Which phrase commonly follows proclivity?','proclivity for','proclivity at from','proclivity under','The noun is naturally followed by for.'),Q(1,'Which person has a proclivity for reading?','someone who often chooses to read','someone who never opens a book','someone who prints books','A proclivity is a repeated inclination.'),Q(1,'Choose a close synonym for proclivity.','tendency','obligation','accident','The word means a behavioral inclination.')]);
P('procrastinate','From Latin procrastinare “put off until tomorrow,” from pro- “forward” + crastinus “of tomorrow.”',C('procrastinate.s1','work habits','Instead of starting the report, she procrastinated by reorganizing her desk for an hour.','她没有开始写报告，而是花一小时整理桌子来拖延。','procrastinated by reorganizing','verb + by-gerund','To procrastinate is repeatedly delay necessary work rather than begin it.'),M('He procrastinated by submitting the report three days before its deadline.','He procrastinated by delaying the report until after the deadline.','Procrastinate means put work off, not finish it early.','meaning'),[Q(1,'What did she delay doing?','starting the report','reorganizing the desk','going home','Procrastinate means put off necessary work.'),Q(1,'How did she procrastinate?','by reorganizing her desk instead','by finishing the report early','by asking for instructions','The example names a distracting activity.'),Q(1,'Which behavior is procrastination?','repeatedly postponing a task','completing a task before its deadline','planning a work schedule','The verb describes delaying action.'),Q(1,'What does the Latin source suggest?','putting something off until tomorrow','announcing it publicly','making it into a process','Procrastinare means postpone until tomorrow.')]);
P('procrastination','From procrastinate + -ion, naming the repeated act or habit of delaying necessary work.',C('procrastination.s1','study skills','Procrastination cost him a night of sleep when he left the essay until the deadline.','他把论文拖到截止日前才写，结果熬夜失眠。','procrastination cost him','noun subject','Procrastination is postponing work that needs to be done.'),M('Her procrastination helped her finish the essay early by preventing any delay.','Her procrastination forced her to rush the essay at the deadline.','Procrastination is delay, not early completion.','meaning'),[Q(1,'What caused him to lose sleep?','delaying the essay until the deadline','finishing the essay early','a procession','Procrastination means postponing necessary work.'),Q(1,'Which action illustrates procrastination?','putting off a report until the last minute','submitting it early','asking a question immediately','The noun names the habit of delaying.'),Q(1,'What does -ion form in procrastination?','a noun for an act or process','a plural adjective','a future tense','The suffix forms an abstract noun.'),Q(1,'What can procrastination lead to?','rushed work near a deadline','more time after early submission','automatic success','The example shows last-minute pressure.')]);
P('procure','From Latin procurare “take care of, manage,” from pro- “for” + curare “care”; the English verb means obtain, often with effort.',C('procure.s1','logistics','The field team procured spare batteries before traveling to the remote station.','野外团队在前往偏远站点前设法备齐了备用电池。','procured spare batteries','verb + object','Procure means obtain something needed, often after a search or effort.'),M('The team procured the batteries by refusing to obtain or bring any.','The team procured the batteries by locating a supplier and buying them.','To procure is to obtain something needed.','meaning'),[Q(1,'What did the team procure?','spare batteries','a royal title','a prison sentence','Procure means obtain something needed.'),Q(1,'When did they obtain them?','before traveling to the remote station','after returning home','during a prizefight','The context says batteries were secured before departure.'),Q(1,'Which action is to procure supplies?','locate and obtain them','leave them unavailable','turn them into a procession','The verb means get something, often with effort.'),Q(1,'Choose a close synonym for procure.','obtain','discard','delay','Procure means acquire or secure.')]);
P('procurement','From procure + -ment, from Latin procurare “manage or take care of”; it names obtaining supplies or the purchasing function.',C('procurement.s1','business','The hospital’s procurement team compared bids before ordering new monitors.','医院采购团队在订购新监护仪前比较了投标方案。','procurement team','noun modifier','Procurement is the process of obtaining supplies or the department that buys them.'),M('The procurement team bought the monitors without comparing bids, suppliers, or prices.','The procurement team compared suppliers and prices before buying the monitors.','Procurement involves obtaining supplies and often evaluating purchases.','meaning'),[Q(1,'What did the team compare?','supplier bids','postcards','prison terms','Procurement includes purchasing decisions.'),Q(1,'What was the hospital ordering?','new monitors','pottery','a procession','The example names medical equipment.'),Q(1,'What does procurement mean?','the process of obtaining supplies','a tendency to delay work','a glass prism','The noun names purchasing or acquisition.'),Q(1,'Which department handles procurement?','the unit that buys supplies','the unit that treats patients only','the postal service','Procurement can name the purchasing department.')]);
P('prod','From an uncertain Germanic source recorded in Middle English for a pointed tool; as a verb it means give a quick push or jab.',C('prod.s1','movement','She gave the stuck button a gentle prod with the tip of a pencil.','她用铅笔尖轻轻戳了一下卡住的按钮。','gave the button a prod','verb + indirect + direct object','Prod can be a quick push with a pointed object or the act of giving one.'),M('He gave the button a prod by carefully avoiding any contact with it.','He gave the button a prod by pushing it once with a pencil tip.','A prod is a quick push or jab; avoiding contact is not one.','meaning'),[Q(1,'What did she use to prod the button?','a pencil tip','a postage stamp','a potted fern','A prod is often made with a pointed object.'),Q(1,'What does prod mean here?','give a quick push','print a picture','set a priority','Prod means jab or push briefly.'),Q(1,'Which action is a prod?','a quick nudge with a stick','a long speech','a quiet procession','The noun names a short pushing action.'),Q(1,'Why did she prod the button?','it was stuck','it was a royal title','it was made of glass','The context explains the reason for the nudge.')]);
P('prodigal','From Latin prodigus “wasteful,” from prodigere “drive forth, squander.”',[C('prodigal.s1','finance','The prodigal heir spent the estate on parties before the family could intervene.','挥霍无度的继承人在家人来得及阻止前就把遗产花在派对上。','prodigal heir','adjective before noun','The adjective describes careless, wasteful spending.'),C('prodigal.s2','character','After years of reckless spending, he admitted he had become a prodigal.','多年挥霍之后，他承认自己成了个败家子。','had become a prodigal','predicate noun','The noun names a person who spends wastefully.'),C('prodigal.s3','generosity','She was prodigal with praise when the apprentices completed careful work.','学徒认真完成工作时，她不吝赞美之词。','prodigal with praise','adjective + with','The less negative adjective sense means lavish or generous in giving.')],M('The prodigal heir carefully saved nearly all the estate and refused every unnecessary expense.','The prodigal heir spent the estate recklessly on luxuries.','Prodigal in the common sense means wasteful with money or resources.','meaning'),[Q(1,'How did the heir spend the estate?','wastefully on parties','carefully on necessary repairs','not at all','Prodigal describes careless, wasteful spending.'),Q(2,'What did he admit he had become?','a person who wastes money','a professional auditor','a prince','The noun prodigal means a wasteful spender.'),Q(3,'What was she generous with?','praise','the family’s estate','a prison sentence','Prodigal with praise means giving it lavishly.'),Q(1,'Which person is prodigal?','someone who squanders an inheritance','someone who saves every coin','someone who prints receipts','The usual adjective sense is wasteful.')]);
P('prodigious','From Latin prodigiosus “wonderful, portentous,” from prodigium “omen, marvel.”',[C('prodigious.s1','quantity','The archive contains a prodigious number of letters—more than two million.','档案里有数量惊人的信件，超过两百万封。','prodigious number','adjective + noun','This sense means amazingly large in amount or size.'),C('prodigious.s2','ability','The young pianist showed prodigious musical skill for someone who had studied only a year.','这位年轻钢琴家只学了一年，却展现出惊人的音乐才华。','prodigious musical skill','adjective + noun','The adjective can mean so impressive that it causes surprise.')],M('The archive held a prodigious number of letters: exactly two, a very small collection.','The archive held a prodigious number of letters: more than two million.','Prodigious means amazingly large, not tiny.','meaning'),[Q(1,'How many letters made the collection prodigious?','more than two million','exactly two','none','Prodigious can mean extraordinarily large in number.'),Q(2,'Why was the pianist’s skill prodigious?','it was remarkable after only a year of study','she had never played before','the piano had no keys','The second sense means impressively exceptional.'),Q(1,'Which quantity is prodigious?','a library with millions of volumes','a desk with one sheet','a pocket with no paper','The word describes an amazingly large amount.'),Q(2,'Choose a close meaning of prodigious in the skill example.','astonishing','ordinary','uncertain','The ability impressed people because it was exceptional.')]);
P('prodigy','From Latin prodigium “omen, portent, marvel”; the modern sense is an exceptionally talented young person.',C('prodigy.s1','education','At age ten, the chess prodigy defeated several experienced adults in a regional tournament.','这位十岁的棋类神童在地区锦标赛中击败了几名经验丰富的成年人。','chess prodigy','noun modifier','A prodigy is a young person with exceptional natural ability.'),M('The chess prodigy was an adult beginner who could not yet move the pieces.','The chess prodigy was a young player with exceptional skill.','A prodigy is usually a young person with remarkable ability.','meaning'),[Q(1,'How old was the chess prodigy?','ten','forty','one hundred','A prodigy is a young person with exceptional skill.'),Q(1,'What did the prodigy accomplish?','defeated experienced players','built a printer','won a pottery prize','The example shows unusually advanced chess ability.'),Q(1,'Which person might be called a prodigy?','a child composing complex music','an adult with no special ability','a postal code','Prodigy refers to an exceptionally talented young person.'),Q(1,'What does prodigy emphasize?','remarkable natural ability at a young age','wasteful spending','a process of manufacture','The source sense is a young person with exceptional talent.')]);
P('produce','From Latin producere “bring forth,” formed from pro- “forward” + ducere “lead”; stress distinguishes the noun PROduce from the verb proDUCE.',[C('produce.s1','manufacturing','The factory can produce five hundred water filters in one shift.','这家工厂一个班次能生产五百个净水器。','produce water filters','verb + object','The verb means make or create something.'),C('produce.s2','effects','The new insulation produced a noticeable drop in heating costs.','新的隔热材料使供暖费用明显下降。','produced a drop','verb + object','Produce can mean cause a result or effect.'),C('produce.s3','presentation','At the meeting, the lawyer produced the signed contract from her folder.','会上，律师从文件夹里拿出了已签署的合同。','produced the contract','verb + object','The verb can mean bring something out for others to see.'),C('produce.s4','agriculture','The market sells fresh produce from nearby farms.','市场出售附近农场的新鲜农产品。','fresh produce','adjective + noun','As a noun pronounced PROduce, it means farm-grown food.')],M('The factory produced filters by destroying them before they were made.','The factory produced filters by assembling and testing them.','Produce means make or bring something into existence.','meaning'),[Q(1,'What did the factory produce?','water filters','heating costs','a signed contract','Produce as a verb means manufacture or make.'),Q(2,'What did the insulation produce?','lower heating costs','a new contract','farm vegetables','Produce can mean cause a result.'),Q(3,'What did the lawyer produce?','a signed contract','a food crop','a prodigious number','Produce can mean bring out for inspection.'),Q(4,'What does fresh produce refer to?','farm-grown food','newly printed books','a computer chip','The noun produce is food grown or obtained by farming.')]);
P('producer','From produce + agent suffix -er; it names a person or entity that makes goods or manages a show’s production.',C('producer.s1','media','The producer coordinated the crew, budget, and filming schedule for the documentary.','制片人协调纪录片的剧组、预算和拍摄日程。','producer coordinated','noun subject','A producer can organize the making of a show or create goods.'),M('The producer managed the documentary by refusing to coordinate the crew or schedule.','The producer managed the documentary by coordinating its crew and filming schedule.','A producer organizes or manages the making of a show.','meaning'),[Q(1,'What did the producer coordinate?','crew, budget, and schedule','a prison sentence','a royal principality','A media producer manages a show’s production.'),Q(1,'Who is a producer?','someone who manages a show’s making','a viewer who watches it','a professor who grades it','The noun names a person involved in production.'),Q(1,'Which company is a producer?','a firm that makes goods','a firm that buys no materials','a postal code','The word can name an entity that produces goods.'),Q(1,'What is not a producer’s role in the example?','coordinating filming','managing the budget','organizing the crew','The context lists the producer’s responsibilities.')]);
P('product','From Latin productum “something brought forth,” from producere “bring forward.”',[C('product.s1','commerce','The company launched a compact product designed for small kitchens.','公司推出了一款适合小厨房使用的紧凑型产品。','launched a product','verb + object','A product is something made or grown for sale.'),C('product.s2','result','The mural was the product of months of work by local students.','这幅壁画是当地学生数月努力的成果。','product of months of work','of-phrase','Product can mean a result of a process or activity.'),C('product.s3','mathematics','The product of six and seven is forty-two.','六乘七的乘积是四十二。','product of six and seven','of-phrase','In mathematics, product is the result of multiplication.')],M('The product of six and seven is thirteen.','The product of six and seven is forty-two.','A product in multiplication is the result; 6 × 7 = 42.','measurement'),[Q(1,'What did the company launch?','an item designed for sale','a result of subtraction','a prison','Product can mean a good made for sale.'),Q(2,'What was the mural?','the result of months of student work','a commercially sold kitchen device','a multiplication answer','Product can mean the result of work.'),Q(3,'What is six multiplied by seven?','forty-two','thirteen','forty-nine','The mathematical product is 42.'),Q(1,'Which item is a product?','a manufactured appliance offered for sale','an idea never made or grown','a postal route','The first sense is something made for sale.')]);
P('production','From Latin productio “a lengthening, bringing forth,” from producere; it means manufacturing or the amount produced.',[C('production.s1','industry','Production of the new electric buses began at the factory in March.','新型电动公交车于三月在工厂开始生产。','production of the buses','of-phrase','This sense names the process of making goods.'),C('production.s2','output','The drought reduced wheat production by nearly a third.','干旱使小麦产量减少了近三分之一。','wheat production','noun modifier','Production can also mean the quantity made or grown.')],M('The drought reduced wheat production by increasing the harvest by a third.','The drought reduced wheat production by lowering the harvested amount.','Production can mean output; a reduction means less was harvested.','meaning'),[Q(1,'What began at the factory?','manufacturing the new buses','a public procession','a postmortem','Production can mean the process of making goods.'),Q(2,'What did the drought reduce?','the amount of wheat harvested','the factory opening date','the bus design','Production can mean output quantity.'),Q(1,'Which activity is production?','making goods in a factory','using a product at home','buying a postcard','The source sense is the process of manufacturing.'),Q(2,'If production rises, what happens?','more items are made or grown','fewer items exist','the factory closes automatically','The quantity sense concerns output.')]);
P('productive','From product + -ive, ultimately Latin producere; it describes producing useful things or achieving good results.',C('productive.s1','work','The team had a productive morning and completed the safety review before lunch.','团队上午效率很高，午饭前就完成了安全检查。','productive morning','adjective before noun','Productive means achieving useful output or good results.'),M('The team had a productive morning but completed no tasks and made no progress.','The team had a productive morning and completed the safety review.','Productive describes work that produces useful results.','meaning'),[Q(1,'What made the morning productive?','the team completed the safety review','the team did no work','the lunch was delayed','Productive means achieving useful results.'),Q(1,'Which day is productive?','one when important work is completed','one with no output at all','one spent avoiding every task','The adjective describes effective output.'),Q(1,'What does productive modify?','morning','team','review','It appears before morning.'),Q(1,'Choose a close meaning for productive.','fruitful','wasteful','inactive','Productive means producing useful things or results.')]);
P('productivity','From productive + -ity; it measures output per worker or machine, or how efficiently resources are used.',[C('productivity.s1','manufacturing','The new cutter raised each worker’s productivity from twelve parts per hour to twenty.','新切割机把每位工人的产能从每小时十二件提高到二十件。','worker’s productivity','possessive noun','Productivity can mean the amount produced by each worker or machine.'),C('productivity.s2','time management','Shorter meetings improved the team’s productivity by freeing time for field work.','缩短会议提高了团队效率，让大家有时间开展实地工作。','improved productivity','verb + object','Productivity can also refer to efficient use of time and resources.')],M('The cutter improved productivity even though workers produced fewer parts in the same hours.','The cutter improved productivity by helping workers produce more parts in the same hours.','Productivity reflects output relative to resources or time.','measurement'),[Q(1,'How did the cutter change output?','from twelve to twenty parts per hour','from twenty to twelve','it stopped all production','Productivity can measure output per worker and time.'),Q(2,'Why did shorter meetings improve productivity?','they freed time for field work','they increased meeting length','they reduced every useful task','This sense concerns efficient use of time.'),Q(1,'What can productivity measure?','output per worker or machine','the color of a product','the number of meetings only','The first sense measures output.'),Q(2,'Which change can improve productivity?','using resources more efficiently','wasting more time','producing less with the same effort','The second sense is efficient use of time or resources.')]);
P('products','Plural of product; from Latin productum “something produced,” it refers to goods made or sold.',C('products.s1','retail','The store recalled several products after tests found a defect in their batteries.','检测发现电池存在缺陷后，商店召回了几种产品。','recalled several products','verb + object','Products are goods that are manufactured or sold.'),M('The store recalled several products because tests proved every battery was safe and defect-free.','The store recalled several products because their batteries had a defect.','A recall responds to a safety or quality problem.','meaning'),[Q(1,'What did the store recall?','several goods it sold','a court proceeding','a professor','Products are items made or sold.'),Q(1,'Why were the products recalled?','their batteries had defects','they were too popular','they contained no batteries','The example explains the safety concern.'),Q(1,'Which word is the plural of product?','products','produce','production','Products is the plural noun form.'),Q(1,'What can a product be?','a manufactured item offered for sale','a series of legal steps','an act of prayer','The source sense is a good that is made or sold.')]);
P('profane','From Latin profanus “outside the temple,” formed from pro “before/outside” + fanum “temple”; it can mean irreverent or nonreligious.',[C('profane.s1','religion','The guide asked visitors not to use profane language inside the sacred hall.','导览员请访客不要在神圣大厅内说亵渎性语言。','profane language','adjective before noun','This sense shows disrespect for God or holy things.'),C('profane.s2','worldly','The collection includes both sacred hymns and profane songs about ordinary life.','这套作品既有神圣赞美诗，也有描写日常生活的世俗歌曲。','profane songs','adjective before noun','Profane can mean ordinary or worldly rather than religious.'),C('profane.s3','desecration','Vandals profaned the memorial by carving insults into its stone.','破坏者在纪念碑石上刻下侮辱性文字，亵渎了它。','profaned the memorial','verb + object','As a verb, profane means treat something holy with disrespect.')],M('The guide called the respectful hymn profane because it honored the sacred figure.','The guide called the insulting language profane because it showed disrespect for the sacred.','Profane means irreverent or disrespectful toward holy things.','meaning'),[Q(1,'What kind of language did the guide forbid?','irreverent language','a quiet prayer','a scientific report','Profane can describe language disrespectful of holy things.'),Q(2,'What were the songs about?','ordinary worldly life','only sacred worship','a court procedure','Profane can mean nonreligious or worldly.'),Q(3,'How did the vandals profane the memorial?','they carved insults into it','they cleaned its stone','they praised its history','The verb means desecrate or treat disrespectfully.'),Q(1,'Which item is profane in the irreverent sense?','an insult directed at a sacred figure','a hymn of worship','a respectful silence','Profane indicates disrespect toward holy things.')]);
P('profess','From Latin profiteri “declare publicly,” from pro- “forth” + fateri “confess”; senses include claim, openly declare belief, or teach a subject.',[C('profess.s1','claims','He professed to know the answer, but could not explain his calculation.','他声称知道答案，却解释不出自己的计算过程。','professed to know','verb + infinitive','Profess can mean claim something is true, sometimes falsely.'),C('profess.s2','belief','The candidate professed a strong commitment to equal treatment.','候选人公开表示坚定致力于平等对待。','professed a commitment','verb + noun','It can mean state a belief or feeling openly.'),C('profess.s3','academia','At the university, she professes medieval history and supervises graduate research.','她在大学讲授中世纪史，并指导研究生研究。','professes medieval history','verb + subject','The formal verb can mean teach a subject as a professor.')],M('He professed to know the answer but demonstrated his knowledge by refusing to explain it and getting it wrong.','He professed to know the answer, though his failed explanation cast doubt on the claim.','Profess can mean claim; the context indicates the claim may not be true.','meaning'),[Q(1,'What did he claim?','that he knew the answer','that he taught medieval history','that he owned a printer','Profess can mean claim something, sometimes falsely.'),Q(2,'What did the candidate state openly?','commitment to equal treatment','a postal schedule','a medical procedure','The second sense is to declare beliefs or feelings.'),Q(3,'What does she do at the university?','teaches medieval history','prints medieval books','runs a principality','Profess can formally mean teach a subject.'),Q(1,'Which sentence uses profess as “claim”?','She professed to know the route.','She professes history at the university.','She professed her faith openly.','The infinitive construction expresses a claim.')]);
P('profession','From Old French profession and Latin professio “public declaration,” from profiteri “declare openly”; it can mean skilled occupation, its members, or a declaration of belief.',[C('profession.s1','careers','Teaching is a profession that requires specialized training and continuing study.','教学是一种需要专门训练和持续学习的职业。','a profession that requires','noun + relative clause','A profession is a job requiring special study or qualifications.'),C('profession.s2','community','The medical profession issued joint guidance on the new treatment.','医学界就这种新疗法发布了联合指南。','medical profession issued','collective noun','Profession can mean all people working in a type of skilled job.'),C('profession.s3','belief','Her profession of faith was made openly at the community meeting.','她在社区会议上公开表明了自己的信仰。','profession of faith','of-phrase','Profession can mean a public statement of a belief or feeling.')],M('Teaching was called a profession even though it required no specialized knowledge or training.','Teaching was called a profession because it required specialized training and expertise.','A profession is a skilled occupation requiring study or qualifications.','meaning'),[Q(1,'Why is teaching a profession?','it requires specialized training','it requires no skill','it is a postage label','The occupational sense involves special study or qualifications.'),Q(2,'Who issued the medical guidance?','the people working in medicine collectively','one patient','a printer','Profession can mean all practitioners in a field.'),Q(3,'What was made openly at the meeting?','a declaration of faith','a postal delivery','a math product','Profession can mean a public declaration.'),Q(1,'Which job is commonly called a profession?','medicine','a one-time household chore','a prison sentence','Professions usually require specialized preparation.')]);
P('professional','From profession + -al; as an adjective it means meeting a trained worker’s standard, and as a noun it names a skilled worker.',[C('professional.s1','conduct','The technician gave a professional explanation and answered the client’s questions patiently.','技术员作了专业的解释，并耐心回答客户的问题。','professional explanation','adjective before noun','Professional can describe skill and conduct expected of trained workers.'),C('professional.s2','employment','A professional inspected the wiring before the building reopened.','大楼重新开放前，一位专业人员检查了电线。','a professional inspected','noun subject','A professional is someone whose job requires special training.')],M('The technician gave a professional explanation by refusing to answer questions and insulting the client.','The technician gave a professional explanation and answered questions respectfully.','Professional behavior is competent and respectful.','meaning'),[Q(1,'How did the technician explain the issue?','with skill and patience','with insults','without any answer','Professional can describe competent conduct.'),Q(2,'Who inspected the wiring?','a trained specialist','a prisoner','a postcard','A professional is someone with specialized training.'),Q(1,'Which action is professional?','explaining a repair clearly and courteously','mocking a client','guessing without checking','The adjective refers to the expected quality of trained work.'),Q(2,'Which person is a professional?','a specialist whose job requires training','a casual visitor','a piece of equipment','The noun means a trained worker.')]);
P('professionalism','From professional + -ism, naming the qualities of competence, reliability, and ethical conduct in a profession.',C('professionalism.s1','workplace','Even under pressure, the nurse showed professionalism by protecting patient privacy and explaining the delay.','即使压力很大，护士仍保护患者隐私并解释延误，表现出职业精神。','showed professionalism','verb + object','Professionalism includes competence, reliability, and ethical behavior.'),M('The nurse showed professionalism by disclosing private records to strangers and refusing to explain the delay.','The nurse showed professionalism by protecting records and communicating the delay clearly.','Professionalism includes ethical care, confidentiality, and reliable communication.','meaning'),[Q(1,'How did the nurse show professionalism?','protected privacy and explained the delay','shared private records','ignored the patient','Professionalism includes ethical conduct and competence.'),Q(1,'Which quality is part of professionalism?','reliability','carelessness','deception','The source sense includes reliability.'),Q(1,'What does -ism form in professionalism?','a noun for a set of qualities','a past-tense verb','a plural noun','-ism names a quality or system.'),Q(1,'Which behavior is professional?','keeping patient information confidential','posting it publicly','altering the records','Ethical conduct is part of professionalism.')]);
P('professionals','Plural of professional; from profession + -al, it names people whose jobs require specialized training.',C('professionals.s1','workplace','The hospital invited professionals from several fields to discuss emergency planning.','医院邀请了多个领域的专业人员讨论应急规划。','professionals from several fields','plural noun','Professionals are people whose work requires specialized skill or training.'),M('The conference invited professionals who had no training or experience in their fields.','The conference invited trained professionals with experience in their fields.','Professionals are skilled workers, not people wholly untrained in the work.','meaning'),[Q(1,'Who attended the emergency-planning discussion?','trained people from several fields','only postal codes','the conference room','Professionals are people whose jobs require training.'),Q(1,'Which group are professionals?','qualified engineers and nurses','random visitors without expertise','a row of printers','The plural names skilled workers.'),Q(1,'What does professionals refer to?','more than one professional','one profession as an idea','a professional manner','The -s marks the plural noun.'),Q(1,'Why did the hospital invite them?','for specialized knowledge','to perform a prizefight','to print postcards','Professionals bring trained expertise.')]);
P('professor','From Latin professor “one who declares publicly,” from profiteri “profess”; meanings vary between a senior academic rank and broader U.S. college teaching usage.',[C('professor.s1','academia','The professor chaired the department and led a research group in medieval literature.','这位教授担任系主任，并领导一个中世纪文学研究小组。','professor chaired','noun subject','In many systems, professor is a high-ranking university teacher.'),C('professor.s2','American usage','In the United States, her students call her professor even though her formal title is lecturer.','在美国，学生们称她为教授，尽管她的正式职称是讲师。','call her professor','verb + object + complement','In U.S. usage, professor can refer more broadly to a college or university teacher.')],M('The department professor had no teaching or research role at any college.','The department professor taught and led research at the university.','A professor is a university teacher; the U.S. usage can include a broader range of ranks.','meaning'),[Q(1,'What did the professor lead?','a research group','a postal service','a prison','Professor can be a high-ranking university teacher.'),Q(2,'Why did U.S. students call her professor?','the term can broadly mean a college teacher','she was a prince','she mailed the lecture','American usage applies professor broadly to university teachers.'),Q(1,'Which workplace fits a professor?','a university','a post office only','a pottery kiln','Professors teach at universities.'),Q(2,'What does professor mean in the U.S. context?','a college or university teacher','only the highest rank in every case','a student without a degree','The second sense is broader in American use.')]);
P('proficiency','From proficient, ultimately Latin proficere “make progress, accomplish,” from pro- “forward” + facere “do.”',C('proficiency.s1','language learning','Her proficiency in Spanish let her interpret the interview without pausing to translate each sentence.','她的西班牙语熟练度让她无需逐句停下来翻译就能为访谈口译。','proficiency in Spanish','noun + in','Proficiency is a good level of skill in using something.'),M('Her proficiency in Spanish prevented her from understanding even simple sentences.','Her proficiency in Spanish allowed her to understand and interpret the interview.','Proficiency means a good level of skill, not inability.','meaning'),[Q(1,'What did her Spanish proficiency allow?','interpret the interview smoothly','forget every word','repair a printer','Proficiency is skill in using a language.'),Q(1,'Which phrase names a proficiency?','proficiency in Spanish','proficiency under a prison','proficiency of a postcard','The noun commonly takes in + skill area.'),Q(1,'What does proficiency measure?','a person’s level of skill','the cost of postage','the number of products','It means a good level of ability.'),Q(1,'Who has proficiency in a language?','someone able to use it skillfully','someone who cannot understand it','a person who only owns a dictionary','Proficiency indicates competence.')]);
P('proficient','From Latin proficiens, present participle of proficere “make progress, accomplish”; it describes someone skilled at an activity.',C('proficient.s1','technology','After practice, the volunteers became proficient at using the emergency radio.','经过练习，志愿者们熟练掌握了应急无线电的使用。','proficient at using','adjective + at-gerund','Proficient means skilled enough to perform an activity well.'),M('The proficient operator could not use the radio after months of successful training.','The proficient operator used the radio accurately after months of training.','Proficient describes skill gained through ability or practice.','meaning'),[Q(1,'What did the volunteers learn to use?','an emergency radio','a prism','a cooking pot','They became skilled at operating the radio.'),Q(1,'What does proficient mean?','skilled at an activity','new to an activity','unable to perform it','The adjective means able to do something well.'),Q(2,'Who is a proficient?','someone who can perform a skill well','a machine that prints pages','a person’s privacy','The less common noun sense names a skilled person.'),Q(1,'Which phrase is standard?','proficient at using the radio','proficient on using the radio','proficient to use the radio','Proficient is commonly followed by at + activity.')]);
P('proficiently','From proficient + adverb suffix -ly; it means with the skill expected of a proficient person.',C('proficiently.s1','work skills','The trainee used the diagnostic tool proficiently after several weeks of supervised practice.','经过数周监督练习后，实习人员熟练地使用了诊断工具。','used the tool proficiently','adverb modifying verb','Proficiently describes skillful, competent performance.'),M('The trainee used the diagnostic tool proficiently by making repeated basic errors.','The trainee used the diagnostic tool proficiently after learning its controls.','Proficiently means with skill, which is inconsistent with repeated basic mistakes.','meaning'),[Q(1,'How did the trainee use the tool?','skillfully','without understanding it','by mailing it','Proficiently means with competence.'),Q(1,'What did the trainee use?','a diagnostic tool','a princely title','a prison','The example identifies the instrument.'),Q(1,'Which phrase does proficiently modify?','used the tool','diagnostic tool','the trainee','The adverb modifies the verb used.'),Q(1,'What helped the trainee use it proficiently?','weeks of supervised practice','no instruction at all','a posthumous award','Practice developed the skill described.')]);
